const lastFuelPrice = () => S.fuelPrice || (fuelLog.length ? fuelLog[fuelLog.length - 1].price : 0);
function parseFuel(n) {
  const nums = [...n.matchAll(/(\d+(?:[.,]\d+)?)\s*(ευρω|€|λιτρ|το λιτρο|ανα λιτρο)?/g)].map((m) => ({ v: parseFloat(m[1].replace(',', '.')), u: m[2] || '' }));
  let total = 0, liters = 0, price = 0;
  nums.forEach((x) => { if (/λιτρο/.test(x.u) && x.v < 5) price = x.v; else if (/λιτρ/.test(x.u)) liters = x.v; else if (/ευρω|€/.test(x.u)) { if (x.v < 4) price = x.v; else total = x.v; } else if (x.v < 4) price = x.v; else if (!total) total = x.v; });
  if (!price) price = lastFuelPrice();
  if (total && price && !liters) liters = total / price; if (liters && price && !total) total = liters * price; if (total && liters && !price) price = total / liters;
  return { total, liters, price };
}
async function tripCost(raw, n) {
  const dm = n.match(/(?:να παω|να παμε|για|μεχρι|προσ|στο|στη|στην|στον)\s+(?:το |τη |την |τον )?([^\d]+?)(?:\s+απο\s+.+?)?(?:\s+και πισω|\s+με επιστροφη|\s+και να γυρισω)?$/);
  if (!dm) return null; const om = n.match(/απο\s+(?:το |τη |την |τον )?(.+?)(?:\s+(?:για|μεχρι|προσ|στο|στη|στην|στον|και)\s|$)/);
  const dest = rawSpan(raw, n, dm[1].trim()), origin = om ? rawSpan(raw, n, om[1].trim()) : (S.cities || 'Αθήνα').split(',')[0].trim();
  Core.set('thinking'); Sound.think();
  const [a, b] = await Promise.all([geocode(origin), geocode(dest)]); if (!a || !b) return `Δεν βρήκα ${!a ? origin : dest} στον χάρτη.`;
  const j = await fetchJSON(`https://router.project-osrm.org/route/v1/driving/${a.lon},${a.lat};${b.lon},${b.lat}?overview=false`); const rt = j?.routes?.[0]; if (!rt) return 'Η υπηρεσία διαδρομών δεν απάντησε. Δοκιμάστε ξανά.';
  const round = /(και πισω|με επιστροφη|να γυρισω|πηγαινε ελα)/.test(n) ? 2 : 1, km = (rt.distance / 1000) * round, price = lastFuelPrice() || 1.85, lit = (km * (S.consumption || 6.5)) / 100;
  return `Από ${a.name} προς ${b.name}${round === 2 ? ' με επιστροφή' : ''}: ${Math.round(km)} χιλιόμετρα, περίπου ${Math.floor(rt.duration * round / 3600)} ώρες και ${Math.round((rt.duration * round % 3600) / 60)} λεπτά οδήγηση. Με κατανάλωση ${String(S.consumption || 6.5).replace('.', ',')} λίτρα στα εκατό θα χρειαστείτε ${Math.round(lit)} λίτρα, δηλαδή περίπου ${eur(lit * price)} καύσιμα με τιμή ${String(price.toFixed(2)).replace('.', ',')} ευρώ το λίτρο. Τα διόδια δεν περιλαμβάνονται.${S.fuelPrice ? '' : ' Πείτε μου «η βενζίνη κάνει 1,90» για ακριβέστερο υπολογισμό.'}`;
}

