const ZODIAC = [['Αιγόκερως', 'αιγοκερ', 1, 19], ['Υδροχόος', 'υδροχο', 2, 18], ['Ιχθείς', 'ιχθ', 3, 20], ['Κριός', 'κριο', 4, 19], ['Ταύρος', 'ταυρ', 5, 20], ['Δίδυμοι', 'διδυμ', 6, 20], ['Καρκίνος', 'καρκιν', 7, 22], ['Λέων', 'λεο|λεων', 8, 22], ['Παρθένος', 'παρθεν', 9, 22], ['Ζυγός', 'ζυγ', 10, 22], ['Σκορπιός', 'σκορπι', 11, 21], ['Τοξότης', 'τοξοτ', 12, 21]];
function signFromDate(d, m) { const z = ZODIAC.find((x) => m === x[2] && d <= x[3]) || ZODIAC.find((x) => x[2] === (m % 12) + 1); return z[0]; }
function signFrom(n) { const z = ZODIAC.find((x) => new RegExp('(^|\\s)(' + x[1] + ')').test(n)); return z ? z[0] : null; }
const H_GEN = ['Η μέρα φέρνει καθαρό μυαλό και την ενέργεια να κλείσετε εκκρεμότητες.', 'Μια απρόσμενη συζήτηση μπορεί να σας ανοίξει νέα πόρτα.', 'Είναι μέρα για υπομονή: ό,τι σπέρνετε τώρα θα καρποφορήσει σύντομα.', 'Η διαίσθησή σας είναι σε υψηλό επίπεδο. Ακούστε την.', 'Μικρές νίκες σήμερα χτίζουν μεγάλη αυτοπεποίθηση.', 'Ιδανική μέρα για να βάλετε τάξη στον χώρο και στις σκέψεις σας.', 'Η δημιουργικότητά σας ξεχωρίζει. Μην την κρύβετε.', 'Αφήστε κάτι παλιό να φύγει για να μπει κάτι καινούργιο.', 'Η τύχη ευνοεί όσους κάνουν το πρώτο βήμα σήμερα.', 'Μια ήρεμη μέρα που σας επιτρέπει να γεμίσετε μπαταρίες.'];
