const H_HEALTH = ['Το σώμα ζητά κίνηση. Ένας περίπατος θα κάνει θαύματα.', 'Πιείτε περισσότερο νερό από το συνηθισμένο.', 'Ο ύπνος είναι το υπερόπλο σας απόψε.', 'Λίγες βαθιές ανάσες θα διώξουν το άγχος.', 'Ελαφρύ φαγητό, περισσότερη ενέργεια.', 'Μια σύντομη διάταση θα σας αναζωογονήσει.'];
const H_COL = ['μπλε', 'πράσινο', 'χρυσό', 'λευκό', 'κόκκινο', 'μωβ', 'πορτοκαλί', 'ασημί', 'τιρκουάζ'];
function hashStr(s) { let h = 2166136261; for (const c of s) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return Math.abs(h); }
function horoscope(sign, d = new Date()) { const h = hashStr(sign + dkey(d)), p = (arr, k) => arr[(h >> k) % arr.length];
  return `Ωροσκόπιο ${sign}, για διασκέδαση: ${p(H_GEN, 1)} Αισθηματικά: ${p(H_LOVE, 3)} Επαγγελματικά: ${p(H_WORK, 5)} Υγεία: ${p(H_HEALTH, 7)} Τυχερός αριθμός ${(h % 49) + 1}, χρώμα ${p(H_COL, 9)}.`; }
const cleanWiki = (s) => s.replace(/<ref[^>]*\/>/g, '').replace(/<ref[^>]*>[\s\S]*?<\/ref>/g, '').replace(/\{\{[^}]*\}\}/g, '').replace(/\[\[(?:[^\]|]*\|)?([^\]]+)\]\]/g, '$1').replace(/'{2,}/g, '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
async function wikiDay(d = new Date()) {
  const ck = Store.get('wday', null); if (ck && ck.k === dkey(d)) return ck;
  const page = `${d.getDate()} ${MONTHS[d.getMonth()]}`, base = 'https://el.wikipedia.org/w/api.php?action=parse&format=json&origin=*&page=' + encodeURIComponent(page);
  const sec = await fetchJSON(base + '&prop=sections'); if (!sec?.parse) return null;
  const get = async (re) => { const s = sec.parse.sections.find((x) => re.test(x.line)); if (!s) return []; const w = await fetchJSON(base + '&prop=wikitext&section=' + s.index); return (w?.parse?.wikitext?.['*'] || '').split('\n').filter((l) => /^\*/.test(l)).map((l) => cleanWiki(l.replace(/^\*+\s*/, ''))).filter((l) => /^\d{1,4}\s*[-–]/.test(l)); };
  const [events, births] = await Promise.all([get(/Γεγονότα/), get(/Γεννήσεις/)]);
  const res = { k: dkey(d), events, births }; Store.set('wday', res); return res;
}
function pickFact(list, seed) { const gr = list.filter((l) => /(Ελλ|Αθήν|Θεσσαλον|Κρήτ|Πειρα|Έλλην|ελληνικ|Πάτρ|Αγρίνι|Μεσολόγγι)/.test(l) && +l.match(/^\d+/)[0] >= 1800); const pool = gr.length ? gr : list.filter((l) => +l.match(/^\d+/)[0] >= 1500); if (!pool.length) return null; return pool[seed % pool.length]; }
const fmtFact = (l) => { const m = l.match(/^(\d{1,4})\s*[-–]\s*(.+)$/); return m ? `Σαν σήμερα, το ${m[1]}: ${m[2]}` : l; };

